1	const PROCESSING_FEE = 5;
2	const FIRST_INSURANCE_SURCHARGE = 0.1;
3	const CURSE_SURCHARGE = 0.5;
4	const LOYALTY_YEARS = 2;
5	const LOYALTY_DISCOUNT = 0.2;
6	const FOLLOW_UP_CONTRACT_DISCOUNT = 0.15;
7	const HIGH_ENCHANTMENT_LEVEL = 5;
8	const HIGH_ENCHANTMENT_SURCHARGE = 0.3;
9	// Price list: each item type has an insurance value and a base premium (10% of the value).
10	type Price = { insuranceValue: number; basePremium: number };
11	const PRICE_LIST: Record<string, Price> = {
12	  sword: { insuranceValue: 1000, basePremium: 100 },
13	  amulet: { insuranceValue: 600, basePremium: 60 },
14	  staff: { insuranceValue: 800, basePremium: 80 },
15	  potion: { insuranceValue: 400, basePremium: 40 },
16	  rune: { insuranceValue: 250, basePremium: 25 },
17	  moonstone: { insuranceValue: 250, basePremium: 25 },
18	};
19	// The building block of 3 alike items applies to components only, never to main items.
20	const COMPONENT_TYPES = new Set(["rune", "moonstone"]);
21	const COMPONENT_BLOCK_SIZE = 3;
22	const COMPONENT_BLOCK_PREMIUM = 60;
23	const CAP_MULTIPLIER = 2;
24	const DEDUCTIBLE = 100;
25	const HALF_REIMBURSEMENT_ENCHANTMENT_LEVEL = 8;
26	const HALF_REIMBURSEMENT_RATE = 0.5;
27	
28	type Item = { type: string; enchantment?: number; cursed?: boolean };
29	type QuoteStep = { op: "quote"; items: Item[] };
30	type Damage = { itemType: string; amount: number };
31	type ClaimStep = { op: "claim"; policy: number; incident: { cause: string; damages: Damage[] } };
32	type Step = QuoteStep | ClaimStep;
33	type Customer = { yearsWithMHPCO: number };
34	type Scenario = { customer: Customer; steps: Step[] };
35	type QuoteResult = { premium: number };
36	type ClaimResult = { payout: number; remainingCap: number };
37	type Result = QuoteResult | ClaimResult;
38	
39	const formsComponentBlock = (type: string, count: number): boolean =>
40	  COMPONENT_TYPES.has(type) && count === COMPONENT_BLOCK_SIZE;
41	
42	const countByType = (items: Item[]): Map<string, number> =>
43	  items.reduce(
44	    (counts, item) => counts.set(item.type, (counts.get(item.type) ?? 0) + 1),
45	    new Map<string, number>(),
46	  );
47	
48	const priceOf = (type: string): Price => {
49	  const price = PRICE_LIST[type];
50	  if (price === undefined) throw new Error(`Unknown item type: ${type}`);
51	  return price;
52	};
53	
54	const basePremiumOf = (type: string): number => priceOf(type).basePremium;
55	
56	const insuranceValueOf = (type: string): number => priceOf(type).insuranceValue;
57	
58	const groupPremium = (type: string, count: number): number =>
59	  formsComponentBlock(type, count) ? COMPONENT_BLOCK_PREMIUM : count * basePremiumOf(type);
60	
61	const calculateBasePremium = (items: Item[]): number =>
62	  [...countByType(items)].reduce((sum, [type, count]) => sum + groupPremium(type, count), 0);
63	
64	// Item-specific modifiers are percentages of the affected item's own base premium.
65	const shareOfItemBasePremium = (item: Item, rate: number): number => basePremiumOf(item.type) * rate;
66	
67	const enchantmentOf = (item: Item): number => item.enchantment ?? 0;
68	
69	const isHighlyEnchanted = (item: Item): boolean => enchantmentOf(item) >= HIGH_ENCHANTMENT_LEVEL;
70	
71	const curseSurcharge = (item: Item): number =>
72	  item.cursed ? shareOfItemBasePremium(item, CURSE_SURCHARGE) : 0;
73	
74	const highEnchantmentSurcharge = (item: Item): number =>
75	  isHighlyEnchanted(item) ? shareOfItemBasePremium(item, HIGH_ENCHANTMENT_SURCHARGE) : 0;
76	
77	const calculateItemSurcharges = (items: Item[]): number =>
78	  items.reduce((sum, item) => sum + curseSurcharge(item) + highEnchantmentSurcharge(item), 0);
79	
80	// Policy-wide modifiers are percentages of the policy base premium (sum of all item base premiums).
81	const isLoyalCustomer = (customer: Customer): boolean => customer.yearsWithMHPCO >= LOYALTY_YEARS;
82	
83	const firstInsuranceSurcharge = (basePremium: number): number => basePremium * FIRST_INSURANCE_SURCHARGE;
84	
85	const loyaltyDiscount = (basePremium: number, customer: Customer): number =>
86	  isLoyalCustomer(customer) ? basePremium * LOYALTY_DISCOUNT : 0;
87	
88	const followUpContractDiscount = (basePremium: number, isFollowUpContract: boolean): number =>
89	  isFollowUpContract ? basePremium * FOLLOW_UP_CONTRACT_DISCOUNT : 0;
90	
91	const calculatePolicyModifiers = (
92	  basePremium: number,
93	  customer: Customer,
94	  isFollowUpContract: boolean,
95	): number =>
96	  firstInsuranceSurcharge(basePremium) -
97	  loyaltyDiscount(basePremium, customer) -
98	  followUpContractDiscount(basePremium, isFollowUpContract);
99	
100	const calculatePremium = (items: Item[], customer: Customer, isFollowUpContract: boolean): number => {
101	  const basePremium = calculateBasePremium(items);
102	  return Math.ceil(
103	    basePremium +
104	      calculateItemSurcharges(items) +
105	      calculatePolicyModifiers(basePremium, customer, isFollowUpContract) +
106	      PROCESSING_FEE,
107	  );
108	};
109	
110	const quote = (step: QuoteStep, customer: Customer, isFollowUpContract: boolean): QuoteResult => ({
111	  premium: calculatePremium(step.items, customer, isFollowUpContract),
112	});
113	
114	const insuranceSum = (items: Item[]): number =>
115	  items.reduce((sum, item) => sum + insuranceValueOf(item.type), 0);
116	
117	const reimbursementRateFor = (item: Item): number =>
118	  enchantmentOf(item) >= HALF_REIMBURSEMENT_ENCHANTMENT_LEVEL ? HALF_REIMBURSEMENT_RATE : 1;
119	
120	// Placeholder: assumes every damage references an insured item (validation comes later).
121	const insuredItemFor = (damage: Damage, insuredItems: Item[]): Item =>
122	  insuredItems.find((item) => item.type === damage.itemType) as Item;
123	
124	// The deductible is charged once per damaged item.
125	const reimbursementFor = (damage: Damage, insuredItems: Item[]): number =>
126	  damage.amount * reimbursementRateFor(insuredItemFor(damage, insuredItems)) - DEDUCTIBLE;
127	
128	// A claim references its policy by the zero-based index of the quote step in the scenario.
129	const insuredItemsOf = (step: ClaimStep, scenario: Scenario): Item[] =>
130	  (scenario.steps[step.policy] as QuoteStep).items;
131	
132	const claim = (step: ClaimStep, scenario: Scenario): ClaimResult => {
133	  const insuredItems = insuredItemsOf(step, scenario);
134	  const cap = insuranceSum(insuredItems) * CAP_MULTIPLIER;
135	  const payout = Math.floor(
136	    step.incident.damages.reduce((sum, damage) => sum + reimbursementFor(damage, insuredItems), 0),
137	  );
138	  return { payout, remainingCap: cap - payout };
139	};
140	
141	export const runScenario = (scenario: Scenario): { results: Result[] } => ({
142	  results: scenario.steps.map((step, index) =>
143	    step.op === "quote" ? quote(step, scenario.customer, index > 0) : claim(step, scenario),
144	  ),
145	});
146

