};'''
new='''// Rounding always favors MHPCO: premiums round up (calculatePremium), payouts round down.
const calculatePayout = (damages: Damage[], insuredItems: Item[]): number =>
  Math.floor(damages.reduce((sum, damage) => sum + reimbursementFor(damage, insuredItems), 0));

const claim = (step: ClaimStep, scenario: Scenario): ClaimResult => {
  const insuredItems = insuredItemsOf(step, scenario);
  const cap = insuranceSum(insuredItems) * CAP_MULTIPLIER;
